import { useState, useEffect, useCallback } from "react";

interface DiagramItem {
  src: string;
  index: string;
  topic: string;
  source: string;
  title: string;
  blurb: string;
  logic: string;
  challenge: string;
  span: string;
}

interface DiagramGroup {
  id: string;
  eyebrow: string;
  title: string;
  italic: string;
  items: DiagramItem[];
}

