interface DiagramCardProps {
  item: DiagramItem;
  onOpen: (item: DiagramItem) => void;
}

function DiagramCard({ item, onOpen }: DiagramCardProps) {
  return (
    <button
      type="button"
      onClick={() => onOpen(item)}
      className={`group relative flex flex-col gap-4 overflow-hidden rounded-2xl border border-border-default/80 bg-bg-raised/55 p-6 text-left backdrop-blur-md transition-all duration-300 hover:-translate-y-1 hover:border-brand-500/40 hover:shadow-[0_30px_80px_-20px_rgba(45,212,191,0.18)] ${item.span}`}
    >
      <header className="flex items-start justify-between gap-3">
        <p className="font-mono text-[11px] uppercase tracking-[0.18em] text-fg-subtle">
          diagram {item.index} · {item.topic}
        </p>
        <span className="font-mono text-[10px] text-fg-subtle">{item.source}</span>
      </header>

      <div className="overflow-hidden rounded-xl border border-border-muted/60 bg-bg-base/60">
        <img
          src={item.src}
          alt={item.title}
          loading="lazy"
          className="h-auto w-full object-contain transition-transform duration-300 group-hover:scale-[1.01]"
        />
      </div>

      <div className="flex flex-col gap-2">
        <h3 className="text-2xl font-medium leading-tight tracking-tight text-fg-base">
          {item.title}
        </h3>
        <p className="max-w-prose text-sm text-fg-muted">{item.blurb}</p>
      </div>

      <dl className="flex flex-col gap-3 border-t border-border-muted/50 pt-4">
        <div>
          <dt className="font-mono text-[10px] uppercase tracking-[0.16em] text-brand-400">
            logic
          </dt>
          <dd className="mt-1 text-[13px] leading-relaxed text-fg-muted">
            {item.logic}
          </dd>
        </div>
        <div>
          <dt className="font-mono text-[10px] uppercase tracking-[0.16em] text-fg-subtle">
            challenge
          </dt>
          <dd className="mt-1 text-[13px] leading-relaxed text-fg-muted">
            {item.challenge}
          </dd>
        </div>
      </dl>

      <span className="font-mono text-[11px] text-brand-400 opacity-0 transition-opacity duration-300 group-hover:opacity-100">
        click to enlarge ↗
      </span>

      <span
        aria-hidden
        className="pointer-events-none absolute inset-x-6 bottom-4 h-px origin-left scale-x-0 bg-brand-500/60 transition-transform duration-300 group-hover:scale-x-100"
      />
    </button>
  );
}

export function DiagramGallery() {
  const [lightbox, setLightbox] = useState<DiagramItem | null>(null);
  const close = useCallback(() => setLightbox(null), []);

  useEffect(() => {
    if (!lightbox) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") close();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightbox, close]);

  return (
    <>
      {GROUPS.map((group) => (
        <section
          key={group.id}
          id={group.id}
          className="border-b border-border-muted/60 py-24 last:border-b-0"
        >
          <div className="mx-auto max-w-7xl px-6">
            <p className="font-mono text-[11px] uppercase tracking-[0.18em] text-fg-subtle">
              {group.eyebrow}
            </p>
            <h2 className="mt-3 max-w-2xl text-4xl font-medium leading-tight tracking-tight text-fg-base sm:text-5xl">
              {group.title}{" "}
              <span className="display-italic text-brand-400">{group.italic}</span>
            </h2>

            <div className="mt-12 grid grid-cols-1 items-start gap-6 lg:grid-cols-12">
              {group.items.map((item) => (
                <DiagramCard key={item.src} item={item} onOpen={setLightbox} />
              ))}
            </div>
          </div>
        </section>
      ))}

      {lightbox ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={lightbox.title}
          onClick={close}
          className="fixed inset-0 z-50 flex flex-col items-center justify-center gap-4 bg-bg-base/90 p-6 backdrop-blur-md"
        >
          <div className="flex w-full max-w-6xl items-center justify-between">
            <p className="font-mono text-[11px] uppercase tracking-[0.18em] text-fg-subtle">
              diagram {lightbox.index} · {lightbox.topic} ·{" "}
              <span className="text-fg-muted">{lightbox.title}</span>
            </p>
            <button
              type="button"
              onClick={close}
              className="rounded-md border border-border-default bg-bg-raised/60 px-3 py-1.5 font-mono text-[12px] text-fg-muted transition-colors hover:border-brand-500/40 hover:text-fg-base"
            >
              close ✕
            </button>
          </div>
          <img
            src={lightbox.src}
            alt={lightbox.title}
            onClick={(e) => e.stopPropagation()}
            className="max-h-[60vh] w-auto max-w-full rounded-lg border border-border-default bg-bg-raised"
          />
          <div
            onClick={(e) => e.stopPropagation()}
            className="grid w-full max-w-4xl gap-5 rounded-xl border border-border-default bg-bg-raised/70 p-5 backdrop-blur-md sm:grid-cols-2"
          >
            <div>
              <p className="font-mono text-[10px] uppercase tracking-[0.16em] text-brand-400">
                logic
              </p>
              <p className="mt-1.5 text-[13.5px] leading-relaxed text-fg-muted">
                {lightbox.logic}
              </p>
            </div>
            <div>
              <p className="font-mono text-[10px] uppercase tracking-[0.16em] text-fg-subtle">
                challenge
              </p>
              <p className="mt-1.5 text-[13.5px] leading-relaxed text-fg-muted">
                {lightbox.challenge}
              </p>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}
